#include "../Source/SessionState.h"
#include "../Source/Plugins/ModulationEditors.h"
#include "../Source/InsertChain.h"
#include <iostream>
#include <new>
#include <cstdlib>
static thread_local bool measuring=false;
static thread_local unsigned allocations=0,deletions=0;
void*operator new(std::size_t n){if(measuring)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void*operator new[](std::size_t n){return ::operator new(n);}
void operator delete(void*p)noexcept{if(measuring&&p)++deletions;std::free(p);}
void operator delete[](void*p)noexcept{::operator delete(p);}
void operator delete(void*p,std::size_t)noexcept{::operator delete(p);}
void operator delete[](void*p,std::size_t)noexcept{::operator delete(p);}
namespace {
unsigned checks=0;
void check(bool b,const juce::String&m){++checks;if(!b)throw std::runtime_error(m.toStdString());}
void set(hem::ModuleProcessor&p,const char*id,float value){auto*parameter=p.state.getParameter(id);check(parameter!=nullptr,"missing parameter");parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
juce::Component*find(juce::Component&c,const juce::String&id){if(c.getComponentID()==id)return &c;for(int i=0;i<c.getNumChildComponents();++i)if(auto*child=find(*c.getChildComponent(i),id))return child;return nullptr;}
std::unique_ptr<hem::ModulationProcessor>make(int number){if(number==23)return std::make_unique<hem::ChorusFlangerPhaserProcessor>();return std::make_unique<hem::RotaryTremoloAutopanProcessor>();}
void run(hem::ModuleProcessor&p,juce::AudioBuffer<float>&b){juce::MidiBuffer midi;measuring=true;p.processBlock(b,midi);measuring=false;}
struct Host:juce::AudioPlayHead{juce::Optional<PositionInfo>getPosition()const override{if(!available)return {};PositionInfo p;if(valid)p.setBpm(bpm);p.setIsPlaying(true);return p;}double bpm=150;bool valid=true,available=true;};
void exactDefaults(){for(int number:{23,24}){
    auto p=make(number);const auto original=hem::SessionState::captureParameters(*p);const auto cached=p->state.copyState();
    for(const auto& spec:p->parameterSpecs()){
        const float raw=p->state.getRawParameterValue(spec.id)->load();auto* parameter=p->state.getParameter(spec.id);
        check(std::abs(raw-spec.initial)<1.e-4f,"startup differs from semantic default");
        check(raw==parameter->convertFrom0to1(parameter->getValue()),"startup raw value is not canonical");
        bool found=false;for(auto child:cached)if(child["id"].toString()==spec.id){check(float(child["value"])==raw,"cached startup tree differs from raw value");found=true;}
        check(found,"cached startup parameter missing");
    }
    auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());
    check(hem::SessionState::captureParameters(*p).isEquivalentTo(original),"editor construction changes exact defaults");
    for(int pass=0;pass<3;++pass){
        auto recalled=make(number);hem::SessionState::restoreParameters(*recalled,original);
        check(hem::SessionState::captureParameters(*recalled).isEquivalentTo(original),"exact session defaults drift on recall");
        juce::MemoryBlock data;p->getStateInformation(data);recalled->setStateInformation(data.getData(),int(data.getSize()));
        check(hem::SessionState::captureParameters(*recalled).isEquivalentTo(original),"exact APVTS defaults drift on recall");
        for(const auto& spec:recalled->parameterSpecs()){auto* parameter=recalled->state.getParameter(spec.id);parameter->setValueNotifyingHost(parameter->getValue());}
        check(hem::SessionState::captureParameters(*recalled).isEquivalentTo(original),"normalized no-op changes canonical defaults");
    }
 }
 std::cout<<"PASS exact canonical startup/raw/tree/editor/APVTS/SessionState defaults and repeated normalized recall\n";
}

void lifecycle(){for(int number:{23,24}){auto p=make(number);for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int n:{1,31,256,1025}){p->prepareToPlay(rate,128);check(p->processingReady(),"prepare readiness");juce::AudioBuffer<float>b(2,n),original(2,n);for(int c=0;c<2;++c)for(int i=0;i<n;++i)b.setSample(c,i,.13f*std::sin(float(i*.02+c)));original.makeCopyOf(b);run(*p,b);for(int c=0;c<2;++c)for(int i=0;i<n;++i)check(b.getSample(c,i)==original.getSample(c,i),"neutral JUCE callback changed audio");check(p->getLatencySamples()==0,"reported latency incorrect");hem::PluginTelemetry::Levels levels;check(p->pluginTelemetry()!=nullptr,"shared telemetry hook missing");check(p->pluginTelemetry()->read(levels)&&levels.valid,"shared meters not valid");check(levels.peak[1]>0&&levels.peak[3]>0,"input and output meters not connected");p->releaseResources();check(!p->processingReady(),"release readiness");}
    p->prepareToPlay(48000,128);Host host;p->setPlayHead(&host);set(*p,"sync",1);set(*p,number==23?"rate":"speed",1);if(number==24)set(*p,"mode",1);juce::AudioBuffer<float>b(2,2400);b.clear();run(*p,b);auto display=p->modulationDisplay();check(display.syncActive&&display.bpm==150&&std::abs(display.rateHz-2.5f)<1.e-5f,"live host BPM not consumed");host.valid=false;run(*p,b);display=p->modulationDisplay();check(!display.syncActive&&!display.tempoAvailable&&display.bpm==0&&std::abs(display.rateHz-1)<1.e-5,"missing host BPM not truthful Hz fallback");host.bpm=std::numeric_limits<double>::quiet_NaN();host.valid=true;run(*p,b);check(!p->modulationDisplay().tempoAvailable,"NaN host BPM accepted");p->setPlayHead(nullptr);
    auto good=p->state.copyState();check(p->migrateParameterState(good).isValid(),"own-root state rejected");juce::ValueTree generic("PARAMETERS");for(auto child:good)generic.addChild(child.createCopy(),-1,nullptr);check(p->migrateParameterState(generic).isValid(),"property-free session PARAMETERS rejected");auto bad=generic.createCopy();bad.setProperty("unexpected",true,nullptr);check(!p->migrateParameterState(bad).isValid(),"foreign session property accepted");bad=generic.createCopy();bad.getChild(0).setProperty("value","12oops",nullptr);check(!p->migrateParameterState(bad).isValid(),"malformed numeric state accepted");bad=generic.createCopy();bad.getChild(0).setProperty("extra",1,nullptr);check(!p->migrateParameterState(bad).isValid(),"foreign parameter property accepted");bad=generic.createCopy();bad.getChild(0).setProperty("value",std::numeric_limits<double>::infinity(),nullptr);check(!p->migrateParameterState(bad).isValid(),"nonfinite state accepted");bad=generic.createCopy();bad.addChild(bad.getChild(0).createCopy(),-1,nullptr);check(!p->migrateParameterState(bad).isValid(),"duplicate state accepted");juce::ValueTree wrong("WRONG_ROOT");for(auto child:generic)wrong.addChild(child.createCopy(),-1,nullptr);check(!p->migrateParameterState(wrong).isValid(),"foreign root accepted");
    for(const auto&s:p->parameterSpecs())set(*p,s.id,s.maximum);juce::MemoryBlock saved;p->getStateInformation(saved);auto restored=make(number);restored->setStateInformation(saved.getData(),int(saved.getSize()));for(const auto&s:p->parameterSpecs())check(restored->state.getRawParameterValue(s.id)->load()==p->state.getRawParameterValue(s.id)->load(),"parameter recall differs");auto forged=generic.createXml();juce::MemoryBlock forgedData;juce::AudioProcessor::copyXmlToBinary(*forged,forgedData);restored->setStateInformation(forgedData.getData(),int(forgedData.getSize()));check(restored->state.getRawParameterValue("mix")->load()==100,"standalone accepted generic session root");
 }
 std::cout<<"PASS 40 JUCE rate/block cases; real tempo/no-tempo/NaN; telemetry; strict roots/properties/values; all-parameter state recall\n";
}
void controls(){for(int number:{23,24}){auto p=make(number);p->prepareToPlay(48000,128);auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());auto*module=dynamic_cast<hem::ModuleEditor*>(editor.get());check(module!=nullptr,"host editor contract");for(const auto&s:p->parameterSpecs()){auto*c=find(*editor,s.id);check(c!=nullptr,juce::String("visible control missing ")+s.id);check(c->getName()==s.name,"accessibility name mismatch");auto*raw=p->state.getRawParameterValue(s.id);check(std::abs(raw->load()-s.initial)<=std::max(.0001f,s.step*.51f),"editor changed initial parameter");if(c->getProperties().contains("modulationChoiceParameter")){for(int i=0;i<=int(s.maximum);++i){const auto id=i?juce::String(s.id)+"_"+juce::String(i):juce::String(s.id);auto*button=dynamic_cast<juce::Button*>(find(*editor,id));check(button&&bool(button->onClick),"visible radio action missing");button->onClick();module->refreshParameterActivity();check(raw->load()==i&&button->getToggleState(),"radio action failed APVTS or feedback");}}else if(auto*combo=dynamic_cast<juce::ComboBox*>(c)){for(int i=1;i<=int(s.maximum)+1;++i){combo->setSelectedId(i,juce::sendNotificationSync);check(raw->load()==i-1,"dropdown does not reach APVTS");}}else if(auto*slider=dynamic_cast<juce::Slider*>(c)){check(slider->getDoubleClickReturnValue()==s.initial,"double-click default wrong");check(slider->getTextValueSuffix().trim()==s.unit,"units wrong");for(float value:{s.minimum,s.maximum,s.initial}){slider->setValue(value,juce::sendNotificationSync);check(std::abs(raw->load()-value)<=std::max(.0001f,s.step*.51f),"dial does not reach APVTS");}}else if(auto*button=dynamic_cast<juce::ToggleButton*>(c)){button->setToggleState(true,juce::sendNotificationSync);check(raw->load()==1,"toggle on failed");button->setToggleState(false,juce::sendNotificationSync);check(raw->load()==0,"toggle off failed");}else check(false,"unknown bound control");set(*p,s.id,s.initial);for(auto size:{juce::Point<int>(1000,563),juce::Point<int>(1280,720),juce::Point<int>(1672,941)}){editor->setSize(size.x,size.y);check(editor->getLocalBounds().contains(c->getBounds()),"control out of bounds");}}
    if(number==23){set(*p,"mode",0);module->refreshParameterActivity();check(find(*editor,"delay")->isEnabled()&&!find(*editor,"center")->isEnabled()&&!find(*editor,"stages")->isEnabled(),"chorus mode activation");set(*p,"mode",2);module->refreshParameterActivity();check(!find(*editor,"delay")->isEnabled()&&find(*editor,"center")->isEnabled()&&find(*editor,"stages")->isEnabled(),"phaser mode activation");}else{set(*p,"mode",1);module->refreshParameterActivity();check(!find(*editor,"ramp")->isEnabled()&&!find(*editor,"rotary")->isEnabled(),"rotary-only activation");set(*p,"mode",0);module->refreshParameterActivity();check(find(*editor,"ramp")->isEnabled()&&find(*editor,"rotary")->isEnabled(),"rotary controls did not reactivate");}
    Host host;p->setPlayHead(&host);set(*p,"sync",1);juce::AudioBuffer<float>b(2,256);b.clear();run(*p,b);module->refreshParameterActivity();auto*slider=dynamic_cast<juce::Slider*>(find(*editor,number==23?"rate":"speed"));check(slider&&slider->getTextValueSuffix().trim()=="c/b","sync unit feedback wrong");slider->setValue(.75,juce::sendNotificationSync);check(slider->getTextFromValue(slider->getValue())=="0.75 c/b","visible synced value loses resolution or duplicates units");p->setPlayHead(nullptr);run(*p,b);module->refreshParameterActivity();check(slider->getTextValueSuffix().trim()=="Hz","fallback unit feedback wrong");check(slider->getTextFromValue(slider->getValue())=="0.75 Hz","visible free-Hz value duplicates units or loses resolution");}
    std::cout<<"PASS all 23 visible APVTS bindings, buttons/dropdowns, startup/reset units, dynamic activation, sync units and resize bounds\n";
}
void chain(){hem::InsertChain c;c.prepare(48000,128);c.installInitial(0,c.stageNode(make(23),48000,128,c.slotLatency()),false);c.installInitial(1,c.stageNode(make(24),48000,128,c.slotLatency()),false);std::array<float,128>l{},r{};for(double rate:{8000.,44100.,48000.,96000.,192000.}){c.prepare(rate,128);const int delay=8*int(std::ceil(rate*.006));std::vector<float>output(size_t(delay+512));for(int start=0;start<int(output.size());start+=37){const int n=std::min(37,int(output.size())-start);l.fill(0);r.fill(0);if(start==0){l[0]=.5f;r[0]=.25f;}measuring=true;c.process(l.data(),r.data(),n);measuring=false;for(int i=0;i<n;++i)output[size_t(start+i)]=l[size_t(i)];}check(c.latencySamples()==delay,"slot budget changed");for(int i=0;i<int(output.size());++i)check(output[size_t(i)]==(i==delay?.5f:0.f),"insert compensation impulse wrong");}
 std::cout<<"PASS real insert chain, both processors, unchanged eight 6 ms slots and exact alignment at five sample rates\n";
}
}
int main(){try{juce::ScopedJuceInitialiser_GUI gui;exactDefaults();lifecycle();controls();chain();check(allocations==0&&deletions==0,"audio callback allocation/free");std::cout<<"PASS "<<checks<<" assertions; zero audio callback allocations/frees\n";return 0;}catch(const std::exception&e){measuring=false;std::cerr<<"FAIL "<<e.what()<<" allocations="<<allocations<<" deletions="<<deletions<<'\n';return 1;}}
